const input = $input.first().json || {};
let month = (input.month || '').toString().trim();
if (!/^\d{4}-\d{2}$/.test(month)) month = $now.plus({ months: 1 }).toFormat('yyyy-MM');
return [{
  json: {
    month,
    feedback: (input.feedback || '').toString().trim(),
    replace_proposed: input.replace_proposed === true,
  },
}];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const target = $('Target month').first().json;
const ctx = $('Get context').first().json;
const offers = rowsOf('Load offers');
const monthStart = DateTime.fromFormat(target.month, 'yyyy-MM', { zone: TZ }).startOf('month');
const monthEnd = monthStart.endOf('month').startOf('day');
const today = DateTime.now().setZone(TZ).startOf('day');

const inMonth = offers.filter((o) => o.month === target.month);
const kept = inMonth.filter((o) => ['approved', 'planned', 'done'].includes(o.status)
  || (o.status === 'proposed' && !target.replace_proposed));
const stale = target.replace_proposed ? inMonth.filter((o) => o.status === 'proposed') : [];
const needed = Math.max(0, 2 - kept.length);

// The last offer before this month bounds the first launch: it needs a run-up of education and stories.
const previous = offers
  .filter((o) => o.month < target.month && ['approved', 'planned', 'done'].includes(o.status) && o.reminder_date)
  .sort((a, b) => (a.reminder_date < b.reminder_date ? 1 : -1))[0];
let minLaunch = monthStart;
if (previous) minLaunch = DateTime.max(minLaunch, parseDate(previous.reminder_date).plus({ days: 8 }));
minLaunch = DateTime.max(minLaunch, today.plus({ days: 7 }));
const maxLaunch = monthEnd.minus({ days: 2 });

const iso = (d) => d.toISODate();
const fixed = {
  '01-01': 'New Year', '02-14': "Valentine's Day", '03-08': "International Women's Day",
  '04-30': 'Reunification Day (holiday 30/4 to 1/5)', '05-01': 'Labour Day', '06-01': "Children's Day",
  '09-02': 'National Day', '10-20': "Vietnamese Women's Day", '11-11': 'Singles Day sales',
  '11-20': "Vietnamese Teachers' Day", '12-24': 'Christmas Eve', '12-31': "New Year's Eve",
};
const lunar = {
  '2026-09-25': 'Mid-Autumn Festival', '2027-02-06': 'Tết Nguyên Đán (Lunar New Year)',
  '2027-09-15': 'Mid-Autumn Festival', '2028-01-26': 'Tết Nguyên Đán (Lunar New Year)',
  '2028-10-03': 'Mid-Autumn Festival', '2029-02-13': 'Tết Nguyên Đán (Lunar New Year)',
  '2029-09-22': 'Mid-Autumn Festival', '2030-02-03': 'Tết Nguyên Đán (Lunar New Year)',
};
const season = {
  1: 'Year-end bonuses (tháng 13) and new-year planning; Tết preparation.',
  2: 'Back to work after Tết; new-year goals and learning plans.',
  3: 'Q1 closes: quarterly reporting.',
  4: 'Long holiday 30/4 to 1/5.',
  5: 'Mid-year job changes begin.',
  6: 'H1 closes: mid-year reviews and reporting; graduation season.',
  7: 'H2 kickoff; fresh graduates look for jobs.',
  8: 'Back-to-school preparation.',
  9: 'New school year; Q3 closes.',
  10: 'Next-year budgets and plans start.',
  11: 'Year-end sales season (11/11, Black Friday).',
  12: 'Year-end reporting and KPI reviews; 12/12 sales; Christmas.',
};
const dates = [];
for (let d = monthStart; d <= monthEnd; d = d.plus({ days: 1 })) {
  const md = d.toFormat('MM-dd');
  if (fixed[md]) dates.push(`${iso(d)}: ${fixed[md]}`);
  if (lunar[iso(d)]) dates.push(`${iso(d)}: ${lunar[iso(d)]}`);
  if (d.month === d.day) dates.push(`${iso(d)}: ${d.day}/${d.month} double-day sales`);
}
if (monthStart.month === 11) {
  let bf = monthStart.set({ day: 1 });
  while (bf.weekday !== 5) bf = bf.plus({ days: 1 });
  bf = bf.plus({ weeks: 3 });
  dates.push(`${iso(bf)}: Black Friday`, `${iso(bf.plus({ days: 3 }))}: Cyber Monday`);
}
dates.sort();

const describe = (o) => [
  `- ${o.month} | ${o.status} | ${o.product} | ${o.offer_type}: ${o.offer} | reason (${o.reason_type}): ${o.reason}`,
  `  launch ${o.launch_date}, reminder ${o.reminder_date}, ends ${o.ends_on}`,
  o.sales_count || o.revenue || o.result_notes
    ? `  result: ${o.sales_count ?? '?'} sales, ${o.revenue ?? '?'} VND. ${o.result_notes || ''}` : '',
].filter(Boolean).join('\n');
const history = offers.filter((o) => o.month < target.month && o.status !== 'proposed').slice(0, 8);
const rejected = inMonth.filter((o) => o.status === 'rejected' || stale.includes(o));

const prompt = [
  `Brand: ${ctx.page_name}. Language: ${ctx.language}.`,
  `Propose ${needed} offer(s) for ${target.month}.`,
  '',
  'Date constraints:',
  `- launch_date between ${iso(minLaunch)} and ${iso(maxLaunch)}.`,
  '- reminder_date 2 to 4 days after launch_date, inside the month.',
  '- ends_on on reminder_date or up to 3 days after it.',
  '- Offers in the same month: a launch at least 7 days after the previous offer\'s reminder_date, so education and stories fit between them.',
  kept.length ? `\nOffers already set for ${target.month} (keep them, plan around their dates):\n${kept.map(describe).join('\n')}` : '',
  rejected.length ? `\nRejected or replaced for ${target.month} (do not propose these again):\n${rejected.map(describe).join('\n')}` : '',
  target.feedback ? `\nThe author's feedback on the last proposal (follow it):\n${target.feedback}` : '',
  `\nDates in ${target.month}:\n${dates.join('\n') || '(none listed)'}\nSeason: ${season[monthStart.month]}\nMany salaries land around the 1st to 5th and the 15th.`,
  `\nPast offers, newest first:\n${history.map(describe).join('\n') || '(none yet)'}`,
  `\nRules learned from past months:\n${ctx.rules || '(none yet)'}`,
  `\nBrand docs:\n${ctx.brand}`,
].join('\n');

return [{
  json: {
    month: target.month,
    needed,
    prompt,
    min_launch: iso(minLaunch),
    max_launch: iso(maxLaunch),
    kept: kept.map((o) => ({ Id: o.Id, launch_date: o.launch_date, reminder_date: o.reminder_date })),
    stale_ids: stale.map((o) => o.Id),
    brand: ctx.brand,
    warnings: ctx.warnings,
  },
}];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const parseJson = (s) => {
  const t = String(s || '').replace(/```(?:json)?/gi, '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('no JSON object in the model output');
  return JSON.parse(t.slice(a, b + 1));
};

// Deterministic checks the strategy depends on. One repair round, then fail loudly.
const input = $('Build proposal input').first().json;
// The repair model answers in JSON mode: the chain node returns the parsed object, not { text }.
const raw = $json.text === undefined ? JSON.stringify($json) : String($json.text);
const errors = [];
let offers = [];
try {
  offers = parseJson(raw).offers;
  if (!Array.isArray(offers)) throw new Error('"offers" is not an array');
} catch (e) {
  errors.push(`Output is not the JSON shape asked for: ${e.message}`);
  offers = [];
}

const TYPES = ['percent_off', 'amount_off', 'free_extra', 'buy_one_get_one', 'bundle'];
const REASONS = ['calendar_date', 'milestone', 'limited_capacity', 'playful'];
const minLaunch = parseDate(input.min_launch);
const maxLaunch = parseDate(input.max_launch);
const monthEnd = parseDate(input.max_launch).endOf('month').startOf('day');
if (!errors.length && offers.length !== input.needed) errors.push(`Expected exactly ${input.needed} offer(s), got ${offers.length}.`);

const clean = offers.map((o, i) => {
  const n = `Offer ${i + 1}`;
  const s = (v) => (v ?? '').toString().trim();
  const list = (v) => (Array.isArray(v) ? v : s(v).split('\n')).map(s).filter(Boolean);
  const c = {
    product: s(o.product), title: s(o.title), offer_type: s(o.offer_type), offer: s(o.offer),
    reason_type: s(o.reason_type), reason: s(o.reason), launch_date: s(o.launch_date),
    reminder_date: s(o.reminder_date), ends_on: s(o.ends_on), landing_url: s(o.landing_url),
    must_know: list(o.must_know), must_feel: list(o.must_feel), rationale: s(o.rationale),
  };
  for (const k of ['product', 'title', 'offer', 'reason', 'rationale']) if (!c[k]) errors.push(`${n}: ${k} is empty.`);
  if (!TYPES.includes(c.offer_type)) errors.push(`${n}: offer_type must be one of ${TYPES.join(', ')}.`);
  if (!REASONS.includes(c.reason_type)) errors.push(`${n}: reason_type must be one of ${REASONS.join(', ')}.`);
  if (c.must_know.length < 3 || c.must_know.length > 5) errors.push(`${n}: must_know needs 3 to 5 lines.`);
  if (c.must_feel.length < 2 || c.must_feel.length > 3) errors.push(`${n}: must_feel needs 2 or 3 lines.`);
  if (c.landing_url && !/^https?:\/\//.test(c.landing_url)) errors.push(`${n}: landing_url must be a full http(s) link or empty.`);
  if (c.landing_url && !input.brand.includes(c.landing_url.replace(/\/$/, ''))) errors.push(`${n}: landing_url does not appear in the brand docs; use an empty string.`);
  const launch = parseDate(c.launch_date);
  const reminder = parseDate(c.reminder_date);
  const ends = parseDate(c.ends_on);
  if (!launch.isValid || !reminder.isValid || !ends.isValid) {
    errors.push(`${n}: dates must be YYYY-MM-DD.`);
  } else {
    if (launch < minLaunch || launch > maxLaunch) errors.push(`${n}: launch_date must be between ${input.min_launch} and ${input.max_launch}.`);
    const gap = reminder.diff(launch, 'days').days;
    if (gap < 2 || gap > 4) errors.push(`${n}: reminder_date must be 2 to 4 days after launch_date.`);
    if (reminder > monthEnd) errors.push(`${n}: reminder_date must stay inside the month.`);
    const tail = ends.diff(reminder, 'days').days;
    if (tail < 0 || tail > 3) errors.push(`${n}: ends_on must be reminder_date or up to 3 days after it.`);
  }
  return c;
});

const windows = [
  ...input.kept.map((k) => ({ name: 'an offer already set', launch: k.launch_date, reminder: k.reminder_date })),
  ...clean.map((c, i) => ({ name: `Offer ${i + 1}`, launch: c.launch_date, reminder: c.reminder_date })),
].filter((x) => parseDate(x.launch).isValid && parseDate(x.reminder).isValid)
  .sort((a, b) => (a.launch < b.launch ? -1 : 1));
for (let i = 1; i < windows.length; i++) {
  const gap = parseDate(windows[i].launch).diff(parseDate(windows[i - 1].reminder), 'days').days;
  if (gap < 7) errors.push(`${windows[i].name} launches ${gap} day(s) after the reminder of ${windows[i - 1].name}; it needs at least 7.`);
}

if (errors.length && $runIndex >= 1) {
  throw new Error('Offer proposal still invalid after a repair: ' + errors.join(' '));
}
return [{ json: { valid: errors.length === 0, errors, offers: clean, raw } }];

