const newToken = () => Array.from({ length: 24 }, () => 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]).join('');

const input = $('Build proposal input').first().json;
return $('Parse offers').last().json.offers.map((o) => ({
  json: {
    ...o,
    month: input.month,
    must_know: o.must_know.join('\n'),
    must_feel: o.must_feel.join('\n'),
    approval_token: newToken(),
  },
}));

const input = $('Build proposal input').first().json;
const rows = $('Offer rows').all().map((i) => i.json);
const saved = $('Save offers').all().map((i) => i.json);
const fmt = (d) => (d ? `${d.slice(8, 10)}/${d.slice(5, 7)}` : '?');
const bullet = (s) => s.split('\n').filter(Boolean).map((l) => `• ${l}`).join('\n');

const elements = [];
rows.forEach((o, i) => {
  const id = saved[i].id;
  if (i > 0) elements.push({ tag: 'hr' });
  elements.push({
    tag: 'markdown',
    content: [
      `**${i + 1}. ${o.title}**`,
      `**${o.product}**: ${o.offer}`,
      `**Why now** (${o.reason_type}): ${o.reason}`,
      `**Launch** ${fmt(o.launch_date)} · **reminder** ${fmt(o.reminder_date)} · **ends** ${fmt(o.ends_on)}`,
      o.landing_url ? `**Link:** ${o.landing_url}` : '',
      `**Must know first:**\n${bullet(o.must_know)}`,
      `**Must feel first:**\n${bullet(o.must_feel)}`,
      `**Rationale:** ${o.rationale}`,
    ].filter(Boolean).join('\n'),
  });
  elements.push({
    tag: 'column_set',
    flex_mode: 'flow',
    columns: [
      ['Approve', 'primary', 'offer_approve'],
      ['Reject', 'danger', 'offer_reject'],
    ].map(([label, type, a]) => ({
      tag: 'column',
      width: 'auto',
      elements: [{
        tag: 'button',
        type,
        text: { tag: 'plain_text', content: `${label} ${i + 1}` },
        behaviors: [{ type: 'callback', value: { a, id, t: o.approval_token } }],
      }],
    })),
  });
});
elements.push({ tag: 'hr' });
elements.push({
  tag: 'markdown',
  content: 'Reply to this card to change them: I propose again with your note. Planning starts when the month has two approved offers.'
    + (input.warnings && input.warnings.length ? `\n⚠️ ${input.warnings.join('\n⚠️ ')}` : ''),
});

return [{
  json: {
    card: {
      schema: '2.0',
      header: { title: { tag: 'plain_text', content: `Offers for ${input.month}` }, template: 'red' },
      body: { elements },
    },
    ref: `month:${input.month}`,
    purpose: 'offer_card',
  },
}];
